import{_ as t,o as e,c as r,ag as n}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"安装并进入平台","description":"使用已测试的 Ubuntu 24，完成 v1.0 安装、首次设置和浏览器登录。","frontmatter":{"title":"安装并进入平台","description":"使用已测试的 Ubuntu 24，完成 v1.0 安装、首次设置和浏览器登录。","status":"reviewed","kind":"tutorial"},"headers":[],"relativePath":"zh/start/index.md","filePath":"zh/快速开始/安装并进入平台.md"}'),s={name:"zh/start/index.md"};function i(o,a,l,h,d,p){return e(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="安装并进入平台" tabindex="-1">安装并进入平台 <a class="header-anchor" href="#安装并进入平台" aria-label="Permalink to &quot;安装并进入平台&quot;">​</a></h1><p>第一次使用 InduFrame，按四步完成：<strong>准备服务器 → 安装平台 → 设置组织管理员密码 → 登录工作台。</strong></p><p>当前版本为 <strong>v1.0</strong>。<strong>优先推荐 Ubuntu 24，目前只测试了这个系统，其他系统尚未测试。</strong> 只负责日常使用时，可让维护人员完成前面三步，再向组织管理员取得公共入口和账号。</p><p>平台已装好并完成设置时，直接看<a href="/induframe-docs/zh/guide/login.html">登录与退出</a>。</p><h2 id="_1-准备服务器和访问地址" tabindex="-1">1. 准备服务器和访问地址 <a class="header-anchor" href="#_1-准备服务器和访问地址" aria-label="Permalink to &quot;1. 准备服务器和访问地址&quot;">​</a></h2><p>按<a href="/induframe-docs/zh/installation/prepare.html">安装前准备</a>确认系统、磁盘余量、完整安装包、访问地址和服务器账号权限。将安装包上传到服务器并完整解压。</p><p><strong>做好后应知道</strong>：安装包在哪里、在哪台服务器操作、以后要用哪个地址访问。</p><h2 id="_2-安装中心" tabindex="-1">2. 安装中心 <a class="header-anchor" href="#_2-安装中心" aria-label="Permalink to &quot;2. 安装中心&quot;">​</a></h2><p>在服务器终端进入安装包文件夹，执行：</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./install.sh</span></span></code></pre></div><p>按提示填写信息，没有特殊安排的选项可用默认值。每项怎么选，见<a href="/induframe-docs/zh/installation/install.html">安装中心</a>。</p><p><strong>做好后应看到</strong>：“InduFrame 中心安装完成。”，安装命令正常结束，并给出公共入口、管理入口和日志路径。保存这三个信息。</p><h2 id="_3-完成首次设置" tabindex="-1">3. 完成首次设置 <a class="header-anchor" href="#_3-完成首次设置" aria-label="Permalink to &quot;3. 完成首次设置&quot;">​</a></h2><p>先打开<strong>管理入口</strong>，用安装时设置的平台账号登录。在“组织管理”找到默认组织，为其管理员设置密码，见<a href="/induframe-docs/zh/installation/first-setup.html">完成首次设置</a>。</p><p><strong>做好后应看到</strong>：“管理员密码已重置”提示。随后打开<strong>公共入口</strong>，用刚设置的组织管理员账号登录。</p><p>这是两组账号：平台账号负责管理组织，组织账号负责进入工作台。不要把安装时的密码直接当作组织管理员密码。</p><h2 id="_4-确认安装成功" tabindex="-1">4. 确认安装成功 <a class="header-anchor" href="#_4-确认安装成功" aria-label="Permalink to &quot;4. 确认安装成功&quot;">​</a></h2><p>按<a href="/induframe-docs/zh/installation/verify.html">确认安装成功</a>检查管理入口、组织登录、页面刷新和退出。打开工程管理，确认能访问，再刷新一次，最后退出。</p><p><strong>做到这里</strong>：你已完成平台安装和基本访问检查。实际工程运行、采集或报警还需要相应配置和业务核对。</p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><p>停在当前失败步骤，记下提示和日志路径，查<a href="/induframe-docs/zh/installation/troubleshooting.html">安装常见问题</a>。没有完成提示时不要跳到下一步，也不要自行删除数据来重试。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>保存两个入口及账号交接信息，日常使用从<a href="/induframe-docs/zh/guide/login.html">登录与退出</a>开始。需要停用或重装时，先了解<a href="/induframe-docs/zh/installation/uninstall.html">卸载平台</a>中的数据保留选择。</p>',23)])])}const m=t(s,[["render",i]]);export{c as __pageData,m as default};
